        "Domat gëtt e Behuelen, eng Bemierkung oder eng Handlung beurteelt: si ass passend oder net passend (nicht angebracht, unangebracht). Verbindungen: ein angebrachter Ton, eine angebrachte Bemerkung.",
        "Am wuertwiertleche Sënn bedeit angebracht och ugemaach, befestegt: Das Schild ist an der Tür angebracht (d'Schëld ass un der Dier ugemaach). Dat ass déiselwecht Partizipform vun anbringen (bringt an, brachte an, hat angebracht)."
