        "Formen: wendet sich ab, wandte (méi seelen wendete) sich ab, hat sich abgewandt (méi seelen abgewendet). De Präfix ab- gëtt ofgetrennt: Sie wendet sich ab.",
        "Ouni Reflexivpronomen bedeit abwenden + Akkusativ ofwenden, verhënneren: eine Gefahr abwenden (eng Gefor ofwenden), an do gi normalerweis déi regelméisseg Forme benotzt: wendete ab, hat abgewendet."
