      "translation": "sech befaassen",
      "explanation": [
        "Haaptiddi: sich befassen ass e reflexivt Verb a bedeit sech mat enger Fro oder engem Thema befaassen, eppes ënnersichen, dacks schrëftlech oder beruflech. No mit steet den Dativ: sich mit etwas befassen.",
        "Formen: befasst sich, befasste sich, hat sich befasst. De Präfix be- ass net trennbar, dofir gëtt et kee ge-.",
        "D'Wuert klengt méi formell wéi sich beschäftigen; et gëtt fir Kommissiounen, Studien, Geriichter a Leit benotzt, déi eng Fro ënnersichen."
      ],
      "examples": [
        {
          "de": "Ich befasse mich mit der Geschichte der Stadt.",
          "lv": "Ech befaasse mech mat der Geschicht vun der Stad."
        },
        {
          "de": "Der Ausschuss befasst sich mit dem Problem.",
          "lv": "De Comité befaasst sech mam Problem."
        },
        {
          "de": "Damit habe ich mich noch nie befasst.",
          "lv": "Domat hunn ech mech nach ni befaasst."
        },
        {
          "de": "Die Studie befasst sich mit den Folgen des Klimawandels.",
          "lv": "D'Studie ënnersicht d'Konsequenze vum Klimawandel."
        }
      ],
