        "Formen: ich schränke mich ein, schränkte mich ein, habe mich eingeschränkt. Mat auf + Akkusativ gëtt gesot, op wat d'Persoun sech beschränkt: sich auf das Nötigste einschränken. Ouni Ergänzung bedeit et dacks d'Ausgabe reduzéieren, spueren.",
