        "An der Meteorologie bezeechent datselwecht Wuert en Héichdrockgebitt, dat normalerweis kloert Wieder bréngt: ein Hoch über Skandinavien. Am iwwerdroene Sënn ass ein Hoch och eng gutt Phas voller Erfolleger.",
