        "Formen: wechselt, wechselte, hat gewechselt. Dat transitivt Verb verlaangt den Akkusativ: etwas wechseln. Fir e Wiessel vun der Richtung benotzt een d'Präpositiounen in/auf/zu: Er wechselt zu einem anderen Verein.",
        "D'Nomen ass der Wechsel (de Wiessel). Wann een eng Saach anescht mécht (ouni se ze ersetzen), benotzt een éischter ändern oder sich verändern."
