      "layout": "standardStudy",
      "translation": "bidden",
      "explanation": [
        "Haaptiddi: bieten heescht ubidden, offréieren (e Präis, eng Méiglechkeet, Hëllef) oder bidden, verschafen (eng Vue, Sécherheet, Ënnerhalung). De Sujet kann eng Persoun sinn, mee och eng Plaz oder eng Institutioun.",
        "Staarkt Verb: er bietet, bot, hat geboten. Meeschtens mam Akkusativ, an d'Persoun am Dativ: jemandem etwas bieten. Fir bei enger Versteigerung oder bei engem Kaf e Präis ze bidden: Wie viel bietest du?",
        "Mat der trennbarer Partikel bezeechent anbieten eng konkret Offer, déi een engem mécht; dat einfacht bieten beschreift dacks, wat eng Plaz oder eng Saach brénge kann."
      ],
      "examples": [
        {
          "de": "Das Hotel bietet einen schönen Blick auf das Meer.",
          "lv": "Den Hotel bitt e schéine Bléck op d'Mier."
        },
        {
          "de": "Wie viel bietest du für das Auto?",
          "lv": "Wéi vill bitts du fir den Auto?"
        },
        {
          "de": "Die Stadt bietet jungen Leuten viele Möglichkeiten.",
          "lv": "D'Stad bitt de jonke Leit vill Méiglechkeeten."
        },
        {
          "de": "Das Museum bietet jeden Sonntag eine Führung.",
          "lv": "De Musée bitt all Sonndeg eng Féierung un."
        }
      ],
      "comparison": [
        {
          "word": "anbieten",
          "meaning": "ubidden",
          "example": "Darf ich Ihnen Tee anbieten? – Dierf ech Iech en Téi ubidden?"
        },
        {
          "word": "gewähren",
          "meaning": "gewähren, accordéieren",
          "example": "Die Bank gewährt einen Kredit. – D'Bank accordéiert e Kredit."
        },
        {
          "word": "geben",
          "meaning": "ginn",
          "example": "Ich gebe dir mein Wort. – Ech ginn dir mäi Wuert."
        }
      ],
      "tip": [
        "Fir ze beschreiwen, wat eng Plaz oder e Service bitt, benotz bieten: Das Hotel bietet WLAN.",
        "Fir enger Persoun eng konkret Saach unzebidden, benotzt een éischter anbieten."
      ],
      "important": [
        "De Präteritum ass bot (an net bietete): er bot, hat geboten."
      ],
