      "translation": "verlafen • oflafen",
      "explanation": [
        "Haaptiddi: verlaufen (ouni sich) heescht op eng bestëmmte Manéier oflafen oder verlafen: Die Prüfung ist gut verlaufen. Et beschreift, wéi eppes sech mat der Zäit entwéckelt huet oder ausgaangen ass.",
        "Formen: es verläuft, es verlief, es ist verlaufen — am Perfekt gëtt sein benotzt. Raimlech kann verlaufen och heeschen, datt eppes sech zitt (e Wee, eng Grenz, eng Linn): Die Grenze verläuft entlang des Flusses.",
        "Mat sich ass et en anert Wuert: sich verlaufen — sech verlafen (de Wee verléieren)."
      ],
      "examples": [
        {
          "de": "Die Prüfung ist gut verlaufen.",
          "lv": "D'Prüfung ass gutt verlaf."
        },
        {
          "de": "Die Operation verlief ohne Probleme.",
          "lv": "D'Operatioun ass ouni Problemer verlaf."
        },
        {
          "de": "Die Grenze verläuft entlang des Flusses.",
          "lv": "D'Grenz leeft laanscht de Floss."
        },
        {
          "de": "Wie ist die Besprechung verlaufen?",
          "lv": "Wéi ass d'Reunioun verlaf?"
        }
      ],
